function stripTags(value) {
  return String(value || '').replace(/<[^>]*>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
}

function extractTag(block, tag) {
  const match = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return match ? stripTags(match[1]) : '';
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

const trends = [];

for (const item of items) {
  const xml = String(item.json.body || item.json.data || item.json || '');
  const blocks = xml.match(/<item[\s\S]*?<\/item>/gi) || xml.match(/<entry[\s\S]*?<\/entry>/gi) || [];

  for (const block of blocks.slice(0, 10)) {
    const title = extractTag(block, 'title');
    const link = extractTag(block, 'link');
    const description = extractTag(block, 'description') || extractTag(block, 'summary') || extractTag(block, 'content');
    const published = extractTag(block, 'pubDate') || extractTag(block, 'published') || extractTag(block, 'updated');
    const idBase = title || link || published;

    if (!idBase) continue;

    trends.push({
      json: {
        id: `rss-${slugify(idBase)}`,
        name: title || 'RSS Trend Signal',
        category: 'AI News',
        status: 'Neu',
        score: 70,
        businessImpact: description ? description.slice(0, 220) : 'Neues RSS-Signal mit möglicher Relevanz für KI-, Produkt- oder Marktbeobachtung.',
        summary: description ? description.slice(0, 260) : 'Dieses Signal wurde aus einem RSS-Feed extrahiert und sollte fachlich geprüft werden.',
        recommendation: 'Signal prüfen, Relevanz bewerten und bei Bedarf Score, Kategorie und Handlungsempfehlung manuell schärfen.',
        source: link || 'RSS Feed',
        timeframe: 'Heute',
        signalType: 'RSS'
      }
    });
  }
}

return trends;

const requiredFields = [
  'id',
  'name',
  'category',
  'status',
  'score',
  'businessImpact',
  'summary',
  'recommendation',
  'source',
  'timeframe',
  'signalType'
];

return items.map((item) => {
  const normalized = {};

  for (const field of requiredFields) {
    normalized[field] = item.json[field] ?? '';
  }

  normalized.id = String(normalized.id || '').trim();
  normalized.name = String(normalized.name || '').trim();
  normalized.category = String(normalized.category || 'AI News').trim();
  normalized.status = String(normalized.status || 'Neu').trim();
  normalized.score = Math.max(0, Math.min(100, Number(normalized.score) || 0));

  return { json: normalized };
}).filter((item) => item.json.id && item.json.name);

const candidates = $input.all(0);
const existingRows = $input.all(1);

const existingIds = new Set(
  existingRows
    .map((item) => String(item.json.id || '').trim())
    .filter(Boolean)
);

return candidates.filter((item) => {
  const id = String(item.json.id || '').trim();
  return id && !existingIds.has(id);
});
